INSERT INTO rag_documents (document_id,repository_index,repository_name,repository_slug,repository_url,retrieval_class,semantic_area,evidence_polarity,evidence_level,specificity_score,concrete_signal_count,word_count,text,topics_json,evidence_areas_json,related_skill_ratings_json,source_fragments_json,provenance_json) VALUES ('repo-031-rd005',31,'TestAnimation',NULL,NULL,'direct_evidence','implementation_skills','positive','interpretive',0.34,0,34,'Section: Implementation Scale

